&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&lt;strong&gt;Standort:&lt;/strong&gt; Raum Hamburg, Bremen, Oldenburg, Kiel, Schwerin&lt;/span&gt;&lt;/p&gt;
